package com.aoo.bcg.wordcard;
import com.aoo.bcg.gamespi.*;import com.aoo.bcg.gamespi.time.*;import java.util.*;
final class BzpSession implements AuthoritativeGameSession{
 enum Phase{WAITING,BAO_ZHUANG,BAO_PAI,PLAYING,FINISHED}private final long room,owner;private final RulePayload rules;private final Map<Integer,Long>players=new LinkedHashMap<>();private final Set<Integer>ready=new LinkedHashSet<>();private final Map<Integer,List<Integer>>hands=new LinkedHashMap<>();private final Map<Integer,Long>points=new LinkedHashMap<>();private final Map<String,String>processedRequests=new LinkedHashMap<>();private final List<Integer>ranking=new ArrayList<>();private final List<Object>events=new ArrayList<>();private final OperationDeadlineArbiter arbiter=new OperationDeadlineArbiter();private Phase phase=Phase.WAITING;private BzpRules.Play lead;private int current=-1,leader=-1,passCount,challenge=-1;private boolean suBao;private long sequence,version;
 BzpSession(long room,long owner,RulePayload rules){if(room<=0||owner<=0)throw new IllegalArgumentException("invalid BZP room");this.room=room;this.owner=owner;this.rules=rules==null?RulePayload.empty():rules;players.put(0,owner);}
 public synchronized GameCommandResult execute(GameCommandRequest r){if(r.roomId()!=room)throw new IllegalArgumentException("invalid BZP room");long uid=id(r.authenticatedUserId());String signature=signature(r);String previous=processedRequests.get(r.requestId());if(previous!=null){if(!previous.equals(signature))throw new IllegalArgumentException("BZP requestId payload conflict");participant(uid);return new GameCommandResult("wordcard.bzp.response",r.requestId(),viewFor(uid));}if(r.sequence()<=sequence)throw new IllegalArgumentException("invalid BZP command order");Map<String,Object>b=r.body().asMap();String a=String.valueOf(b.getOrDefault("action","state"));boolean change=true;switch(a){case"state","CBZPGetRoomInfo"->{participant(uid);change=false;}case"join","CBZPEnterRoom"->join(r.seatId(),uid);case"ready","CBZPReadyRoom"->{own(r.seatId(),uid);waiting();ready.add(r.seatId());}case"start","CBZPStartGame"->start(uid);case"operation","CBZPOpCard"->operate(r,uid);default->throw new IllegalArgumentException("unsupported BZP action");}sequence=r.sequence();processedRequests.put(r.requestId(),signature);if(change){version++;events.add(Map.of("version",version,"after",snapshot()));}return new GameCommandResult("wordcard.bzp.response",r.requestId(),viewFor(uid));}
 private void join(int seat,long uid){waiting();if(seat<0||seat>=4||players.putIfAbsent(seat,uid)!=null)throw new IllegalStateException("bad BZP seat");}
 private void start(long uid){if(uid!=owner)throw new SecurityException("owner only");waiting();if(players.size()<2||!ready.containsAll(players.keySet().stream().filter(x->x!=0).toList()))throw new IllegalStateException("players not ready");List<Integer>deck=deck();Collections.shuffle(deck,new Random(room));for(int seat:players.keySet()){List<Integer>h=new ArrayList<>();for(int i=0;i<13;i++)h.add(deck.removeFirst());hands.put(seat,h);points.put(seat,0L);}current=0;phase=bool("baoZhuang")?Phase.BAO_ZHUANG:bool("baoPai")?Phase.BAO_PAI:Phase.PLAYING;}
 private void operate(GameCommandRequest r,long uid){own(r.seatId(),uid);Map<String,Object>p=map(r.body().asMap().getOrDefault("payload",Map.of()));String op=String.valueOf(p.getOrDefault("operation","PASS"));if(phase==Phase.BAO_ZHUANG){requireTurn(r.seatId());if(op.equals("YING_BAO")||op.equals("SU_BAO")){challenge=r.seatId();suBao=op.equals("SU_BAO");phase=bool("baoPai")?Phase.BAO_PAI:Phase.PLAYING;}else if(op.equals("PASS")){rotate();if(current==0)phase=bool("baoPai")?Phase.BAO_PAI:Phase.PLAYING;}else throw new IllegalArgumentException("BZP bao-zhuang operation required");return;}if(phase==Phase.BAO_PAI){requireTurn(r.seatId());if(op.equals("FAN_BAO")){challenge=r.seatId();phase=Phase.PLAYING;}else if(op.equals("PASS")){rotate();if(current==0)phase=Phase.PLAYING;}else throw new IllegalArgumentException("BZP bao-pai operation required");return;}if(phase!=Phase.PLAYING)throw new IllegalStateException("BZP not playing");requireTurn(r.seatId());if(op.equals("PASS")){if(lead==null||leader==r.seatId())throw new IllegalStateException("cannot pass");if(++passCount>=players.size()-1){current=leader;lead=null;passCount=0;}else rotate();return;}if(!op.equals("OUT"))throw new IllegalArgumentException("BZP OUT/PASS required");BzpRules.Type type=BzpRules.Type.valueOf(String.valueOf(p.get("type")));List<Integer>cards=ints(p.get("cards"));BzpRules.Play play=BzpRules.classify(type,cards);if(!BzpRules.beats(play,lead))throw new IllegalStateException("BZP play does not beat lead");List<Integer>hand=hands.get(r.seatId());List<Integer>remaining=new ArrayList<>(hand);for(int c:cards)if(!remaining.remove(Integer.valueOf(c)))throw new IllegalArgumentException("BZP card not held");hand.clear();hand.addAll(remaining);lead=play;leader=r.seatId();passCount=0;points.compute(r.seatId(),(k,v)->v+cards.stream().mapToInt(BzpRules::point510k).sum()+prize(play));if(hand.isEmpty()){ranking.add(r.seatId());finish();}else rotate();}
 private int prize(BzpRules.Play p){return switch(p.type()){case DOU->BzpRules.eightBombPrize(p.cards().size());case ROLLING_DRAGON->p.cards().size();default->0;};}
 private void finish(){phase=Phase.FINISHED;}
 public synchronized Map<String,Object>viewFor(long uid){Integer mine=seat(uid);Map<Integer,Object>s=new LinkedHashMap<>();players.forEach((pos,p)->{List<Integer>h=hands.getOrDefault(pos,List.of());s.put(pos,Map.of("playerId",p,"ready",ready.contains(pos),"cards",Objects.equals(pos,mine)||phase==Phase.FINISHED?h:Collections.nCopies(h.size(),0),"cardCount",h.size(),"point",points.getOrDefault(pos,0L)));});return Map.of("roomId",room,"gameCode","bzp","phase",phase.name(),"currentSeat",current,"challengeSeat",challenge,"suBao",suBao,"seats",Map.copyOf(s),"stateVersion",version);}
 public synchronized Map<String,Object>authoritativeState(){return snapshot();}public synchronized long stateVersion(){return version;}synchronized List<Object>events(){return List.copyOf(events);}private Map<String,Object>snapshot(){Map<String,Object>x=new LinkedHashMap<>();x.put("schemaVersion",1);x.put("roomId",room);x.put("ownerId",owner);x.put("players",Map.copyOf(players));x.put("ready",List.copyOf(ready));x.put("rules",rules.asMap());x.put("hands",Map.copyOf(hands));x.put("points",Map.copyOf(points));x.put("processedRequests",Map.copyOf(processedRequests));x.put("ranking",List.copyOf(ranking));x.put("phase",phase.name());x.put("current",current);x.put("leader",leader);x.put("passCount",passCount);x.put("challenge",challenge);x.put("suBao",suBao);x.put("sequence",sequence);x.put("stateVersion",version);x.put("lead",lead==null?Map.of():Map.of("type",lead.type().name(),"cards",lead.cards()));return Map.copyOf(x);}
 static BzpSession restore(Map<String,Object>s){if(num(s.get("schemaVersion"))!=1)throw new IllegalArgumentException("bad BZP schema");BzpSession x=new BzpSession(longNum(s.get("roomId")),longNum(s.get("ownerId")),RulePayload.copyOf(map(s.get("rules"))));x.players.clear();map(s.get("players")).forEach((k,v)->x.players.put(Integer.parseInt(k),longNum(v)));for(Object v:(Collection<?>)s.get("ready"))x.ready.add(num(v));map(s.get("hands")).forEach((k,v)->x.hands.put(Integer.parseInt(k),new ArrayList<>(ints(v))));map(s.get("points")).forEach((k,v)->x.points.put(Integer.parseInt(k),longNum(v)));map(s.getOrDefault("processedRequests",Map.of())).forEach((k,v)->x.processedRequests.put(k,String.valueOf(v)));x.ranking.addAll(ints(s.get("ranking")));x.phase=Phase.valueOf(String.valueOf(s.get("phase")));x.current=num(s.get("current"));x.leader=num(s.get("leader"));x.passCount=num(s.get("passCount"));x.challenge=num(s.get("challenge"));x.suBao=Boolean.TRUE.equals(s.get("suBao"));x.sequence=longNum(s.get("sequence"));x.version=longNum(s.get("stateVersion"));Map<String,Object>l=map(s.get("lead"));if(!l.isEmpty())x.lead=BzpRules.classify(BzpRules.Type.valueOf(String.valueOf(l.get("type"))),ints(l.get("cards")));return x;}
 static StatePayload replay(StatePayload base,List<Object>events){Map<String,Object>s=new LinkedHashMap<>(base.asMap());long v=longNum(s.get("stateVersion"));for(Object raw:events){Map<String,Object>e=map(raw);if(longNum(e.get("version"))!=++v)throw new IllegalArgumentException("BZP replay gap");s=new LinkedHashMap<>(map(e.get("after")));}return StatePayload.copyOf(s);}
 public OperationDeadline operationDeadline(){return OperationDeadline.none();}public OperationDeadlineArbiter deadlineArbiter(){return arbiter;}public synchronized List<String>invariantViolations(){return players.containsValue(owner)?List.of():List.of("OWNER_NOT_SEATED");}public synchronized SettlementPayload settlement(int round,String pv){if(phase!=Phase.FINISHED)throw new IllegalStateException("BZP not finished");if(!BzpGameProvider.VERSION.equals(pv))throw new IllegalArgumentException("play version mismatch");int winner=ranking.getFirst();long base=challenge>=0?(suBao?6:3):2;Map<Long,Long>d=new LinkedHashMap<>();players.forEach((seat,player)->d.put(player,seat==winner?base*(players.size()-1):-base));return new SettlementPayload(room,round,pv,d);}
 private static List<Integer>deck(){List<Integer>d=new ArrayList<>();for(int copy=0;copy<2;copy++){for(int suit=1;suit<=4;suit++)for(int rank=1;rank<=13;rank++)d.add(suit*16+rank+copy*256);d.add(0x4e+copy*256);d.add(0x4f+copy*256);}return d;}private void rotate(){List<Integer>x=new ArrayList<>(players.keySet());current=x.get((x.indexOf(current)+1)%x.size());}private void requireTurn(int s){if(s!=current)throw new IllegalStateException("not BZP turn");}private boolean bool(String k){return Boolean.TRUE.equals(rules.asMap().get(k));}private void waiting(){if(phase!=Phase.WAITING)throw new IllegalStateException("started");}private void own(int s,long p){if(!Long.valueOf(p).equals(players.get(s)))throw new SecurityException("seat not owned");}private void participant(long p){if(!players.containsValue(p))throw new SecurityException("not participant");}private Integer seat(long p){return players.entrySet().stream().filter(e->e.getValue()==p).map(Map.Entry::getKey).findFirst().orElse(null);}private static String signature(GameCommandRequest r){return r.sequence()+"|"+r.authenticatedUserId()+"|"+r.seatId()+"|"+r.body().asMap();}private static long id(String v){return longNum(v);}private static int num(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));}private static long longNum(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static List<Integer>ints(Object v){return((Collection<?>)v).stream().map(BzpSession::num).toList();}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object v){Map<String,Object>m=new LinkedHashMap<>();((Map<?,?>)v).forEach((k,x)->m.put(String.valueOf(k),x));return m;}
}
